draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw stick figure eating
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 - 50, 20, 0, 2 * Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 30); // body
  ctx.lineTo(W/2 - 50, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 10); // arm
  ctx.lineTo(W/2 - 70, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 10); // leg
  ctx.lineTo(W/2 - 60, H/2 + 40);
  ctx.stroke();

  // animate arm
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 10); 
  ctx.lineTo(W/2 - 70 + 20 * Math.sin(t), H/2);
  ctx.stroke();

  // draw speech bubble
  ctx.beginPath();
  ctx.arc(W/2 - 120, H/2 - 70, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Yum!', W/2 - 120, H/2 - 70);

  ctx.restore();
}
